#include <DHT.h>
DHT dht({{dht_pin}}, DHT22);
void setup() { Serial.begin(115200); dht.begin(); }
void loop() {
    float t = dht.readTemperature();
    float h = dht.readHumidity();
    int raw = analogRead({{soil_pin}});
    float soil_pct = map(raw, 3000, 1000, 0, 100);
    soil_pct = constrain(soil_pct, 0, 100);
    Serial.printf("T=%.1f H=%.1f soil=%.0f%%\n", t, h, soil_pct);
    delay(5000);
}
